102	  /**
103	   * Re-renders only the repo table and toggle, preserving the Add Repository
104	   * form and its current field values. Called on checkbox toggle.
105	   */
106	  function refreshTable(checked) {
107	    var toggleEl = document.getElementById('strategy-toggle-area');
108	    var tableEl = document.getElementById('strategy-table-area');
109	    if (toggleEl) toggleEl.innerHTML = buildToggleHtml(checked);
110	    if (tableEl) tableEl.innerHTML = '<p class="text-muted" style="font-size:13px">Loading\u2026</p>';
111	
112	    API.listRepos(checked).then(function (repos) {
113	      if (tableEl) tableEl.innerHTML = buildTableHtml(repos);
114	      wireRegisterButtons();
115	      wireToggle();
116	    }).catch(function (err) {
117	      if (tableEl) tableEl.innerHTML = '<p class="error-banner">Failed to load repositories: ' + escapeHtml(err.message || String(err)) + '</p>';
118	      wireToggle();
119	    });
120	  }
121	
122	  /**
123	   * Transforms a raw filesystem directory name into a valid SLUG_REGEX slug.
124	   * Rules applied in order:
125	   *   1. Lowercase
126	   *   2. Replace any character that is not [a-z0-9_-] with a hyphen
127	   *   3. Strip any leading characters that are not alphanumeric
128	   *   4. Collapse consecutive hyphens into a single hyphen
129	   *   5. Fall back to 'repo' if the result is empty
130	   */
131	  function sanitiseSlug(raw) {
132	    var slug = raw
133	      .toLowerCase()
134	      .replace(/[^a-z0-9_-]/g, '-')
135	      .replace(/^[^a-z0-9]+/, '')
136	      .replace(/-{2,}/g, '-');
137	    return slug || 'repo';
138	  }
139	
140	  /** Wires the "Register" buttons on undeclared rows to pre-fill the Add form. */
141	  function wireRegisterButtons() {
142	    var tableEl = document.getElementById('strategy-table-area');
143	    if (!tableEl) return;
144	    tableEl.querySelectorAll('[data-register-folder]').forEach(function (btn) {
145	      btn.addEventListener('click', function () {
146	        var folderName = btn.getAttribute('data-register-folder');
147	        var idInput = document.getElementById('new-repo-id');
148	        var labelInput = document.getElementById('new-repo-label');
149	        var foldersInput = document.getElementById('new-repo-folders');
150	        if (idInput) idInput.value = sanitiseSlug(folderName);
151	        if (labelInput) labelInput.value = folderName;
152	        if (foldersInput) foldersInput.value = folderName;
153	        /* Scroll the Add Repository form into view */
154	        var formCard = document.getElementById('add-repo-form');
155	        if (formCard) formCard.scrollIntoView({ behavior: 'smooth', block: 'start' });
156	        if (idInput) idInput.focus();
157	      });
158	    });
159	  }
160	
161	  /** Wires the Show undeclared checkbox change handler after each re-render. */
162	  function wireToggle() {
163	    var cb = document.getElementById('show-undeclared-cb');
164	    if (!cb) return;
165	    cb.addEventListener('change', function () {
166	      refreshTable(cb.checked);
167	    });
168	  }
169	
170	  function renderList(repos, checked) {
171	    app.innerHTML =
172	      '<div class="page-header">' +
173	        '<h1>Strategy</h1>' +
174	        '<p class="text-muted">Manage repository declarations and strategic vision.</p>' +
175	      '</div>' +
176	      '<div id="strategy-toggle-area">' + buildToggleHtml(checked) + '</div>' +
177	      '<div id="strategy-table-area">' + buildTableHtml(repos) + '</div>' +
178	      '<div class="card mt-24" style="max-width:560px">' +
179	        '<h2 style="margin-top:0">Add Repository</h2>' +
180	        '<form id="add-repo-form">' +
181	          '<div class="form-group">' +
182	            '<label class="form-label" for="new-repo-id">ID <span class="text-muted">(slug, e.g. my-project)</span></label>' +
183	            '<input type="text" id="new-repo-id" class="form-control" placeholder="my-project" required>' +
184	          '</div>' +
185	          '<div class="form-group">' +
186	            '<label class="form-label" for="new-repo-label">Label</label>' +
187	            '<input type="text" id="new-repo-label" class="form-control" placeholder="My Project">' +
188	          '</div>' +
189	          '<div class="form-group">' +
190	            '<label class="form-label" for="new-repo-folders">Folder Names <span class="text-muted">(comma-separated)</span></label>' +
191	            '<input type="text" id="new-repo-folders" class="form-control" placeholder="my-project, my-project-dev">' +
192	          '</div>' +
193	          '<button type="submit" class="btn btn-primary">Add Repository</button>' +
194	          '<div id="add-repo-msg"></div>' +
195	        '</form>' +
196	      '</div>';
197	
198	    wireRegisterButtons();
199	    wireToggle();
200	
201	    var form = document.getElementById('add-repo-form');
202	    if (!form) return;
203	
204	    form.addEventListener('submit', function (e) {
205	      e.preventDefault();
206	      var msgEl = document.getElementById('add-repo-msg');
207	      var id = (document.getElementById('new-repo-id').value || '').trim();
208	      var label = (document.getElementById('new-repo-label').value || '').trim();
209	      var foldersRaw = (document.getElementById('new-repo-folders').value || '').trim();
210	      var folderNames = foldersRaw
211	        ? foldersRaw.split(',').map(function (f) { return f.trim(); }).filter(Boolean)
212	        : [];
213	
214	      if (!id) {
215	        msgEl.innerHTML = '<p class="error-banner">ID is required.</p>';
216	        return;
217	      }
218	
219	      if (!folderNames.length) {
220	        msgEl.innerHTML = '<p class="error-banner">At least one folder name is required.</p>';

221	        return;
222	      }
223	
224	      msgEl.innerHTML = '';
225	      API.createRepo({ id: id, label: label || id, folder_names: folderNames })
226	        .then(function () {
227	          Router.navigate('#/strategy/' + encodeURIComponent(id));
228	        })
229	        .catch(function (err) {
230	          msgEl.innerHTML = '<p class="error-banner">Failed to create repository: ' + escapeHtml(err.message || String(err)) + '</p>';
231	        });
232	    });
233	  }
234	}
235	
236	/* ── renderStrategyDetail ────────────────────────────────────
237	   Renders the repository detail/editor at #/strategy/:repoId.
238	   Shows: editable label, folder names (add/remove), three-field
239	          vision editor (short-term, mid-term, long-term),
240	          save button, breadcrumb navigation.
241	   ─────────────────────────────────────────────────────────── */
242	function renderStrategyDetail(app, repoId) {
243	  showLoading(app);
244	
245	  API.getRepo(repoId).then(function (repo) {
246	    renderDetail(repo);
247	  }).catch(function (err) {
248	    if (err.code === 'NOT_FOUND' || (err.message && err.message.indexOf('404') !== -1)) {
249	      showError(app, 'Repository not found: ' + escapeHtml(repoId));
250	    } else {
251	      showError(app, 'Failed to load repository: ' + (err.message || String(err)));
252	    }
253	  });
254	
255	  function buildFolderListHtml(folderNames) {
256	    if (!folderNames || !folderNames.length) {
257	      return '<p class="text-muted" id="folder-empty-note">No folder names added yet.</p>';
258	    }
259	    return folderNames.map(function (f, i) {
260	      return (
261	        '<div class="folder-entry" style="display:flex;align-items:center;gap:8px;margin-bottom:6px">' +
262	          '<input type="text" class="form-control folder-name-input" data-folder-idx="' + i + '" value="' + escapeHtml(f) + '" style="flex:1">' +
263	          '<button type="button" class="btn btn-danger btn-sm" data-remove-folder="' + i + '">Remove</button>' +
264	        '</div>'
265	      );
266	    }).join('');
267	  }
268	
269	  /* Reads all folder name inputs from the DOM in index order. */
270	  function collectFolderNamesFromDOM() {
271	    var result = [];
272	    document.querySelectorAll('.folder-name-input').forEach(function (inp) {
273	      var val = inp.value.trim();
274	      if (val) result.push(val);
275	    });
276	    return result;
277	  }
278	
279	  function renderDetail(repo) {
280	    var vision = repo.vision || {};
281	    /* Working copy — mutated by add/remove, then merged with DOM on save. */
282	    var folderNames = (repo.folder_names || []).slice();
283	
284	    function rebuildFolderSection() {
285	      var container = document.getElementById('folder-list');
286	      if (container) {
287	        container.innerHTML = buildFolderListHtml(folderNames);
288	        wireRemoveButtons();
289	      }
290	    }
291	
292	    function wireRemoveButtons() {
293	      var container = document.getElementById('folder-list');
294	      if (!container) return;
295	      container.querySelectorAll('[data-remove-folder]').forEach(function (btn) {
296	        btn.addEventListener('click', function () {
297	          /* Capture any in-flight edits before splicing */
298	          folderNames = collectFolderNamesFromDOM();
299	          var idx = parseInt(btn.getAttribute('data-remove-folder'), 10);
300	          folderNames.splice(idx, 1);

